let language=localStorage.guardiasLanguage||"es";
const t=k=>I18N[language][k]??I18N.es[k]??k;
const tr=(k,vars={})=>String(t(k)).replace(/\{(\w+)\}/g,(_,x)=>vars[x]??"");
function iso(d){const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,"0")}-${String(x.getDate()).padStart(2,"0")}`}
function initial(n){return n.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase()}
function monday(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function rotationPeople(){return people.filter(p=>p.inRotation!==false&&p.role!=="viewer"&&!p.alwaysOnDuty)}
function weekForDate(d){const roster=rotationPeople();const m=monday(d);const diff=Math.floor((m.getTime()-startDate.getTime())/604800000);if(!roster.length)return {person:null,start:m,end:addDays(m,6),index:-1};const startPersonId=people[startIndex]?.id;let rosterStart=roster.findIndex(p=>String(p.id)===String(startPersonId));if(rosterStart<0)rosterStart=0;const rIndex=((rosterStart+diff)%roster.length+roster.length)%roster.length;return {person:roster[rIndex],start:m,end:addDays(m,6),index:people.indexOf(roster[rIndex])}}
function fmt(d){const locale=language==="en"?"en-US":"es-NI";return d.toLocaleDateString(locale,{day:"2-digit",month:"short"}).replaceAll(".","").toUpperCase()}
function isSame(a,b){return iso(a)===iso(b)}
function showToast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove("show"),2600)}
function isValidMonday(d){return d instanceof Date&&!Number.isNaN(d.getTime())&&d.getDay()===1}
function parseStartDate(value){if(!value)return null;const d=new Date(value+"T00:00:00");return Number.isNaN(d.getTime())?null:d}
function loadPeopleState(){
  try{
    const saved=JSON.parse(localStorage.guardiasPeople||"null");
    if(Array.isArray(saved)&&saved.length){
      const base=people.map(p=>({...p}));
      const savedById=new Map(saved.map(p=>[String(p.id||p.network),p]));
      const merged=base.map(p=>{
        const old=savedById.get(String(p.id))||savedById.get(String(p.network));
        return old?{...p,...old}:p;
      });
      const baseKeys=new Set(base.map(p=>String(p.id||p.network)));
      saved.forEach(p=>{const key=String(p.id||p.network);if(!baseKeys.has(key))merged.push(p)});
      people.splice(0,people.length,...merged);
    }
  }catch{}
  people.forEach((p,i)=>{
    p.id=p.id||`u-${String(i+1).padStart(3,'0')}`;
    p.role=p.role||(p.admin?'admin':'member');
    p.alwaysOnDuty=!!p.alwaysOnDuty;
    p.inRotation=p.alwaysOnDuty?false:(p.role==='viewer'?false:(p.inRotation!==false));
    const c=LOCAL_CREDENTIALS[p.network];
    if(c){p.password=p.password||c.password;p.email=p.network==='rdumas'?'angelramses2703@gmail.com':(p.email||c.email)}
  });
  savePeopleState();
}
function savePeopleState(){localStorage.guardiasPeople=JSON.stringify(people);localStorage.guardiasPeopleVersion="16"}
function loadState(){try{const s=JSON.parse(localStorage.guardiasState||"null");if(!s||![15,15.3,16].includes(Number(s.version)))throw new Error("RESET_V16");const savedId=s.startPersonId;const idxById=people.findIndex(p=>String(p.id)===String(savedId));const idx=Number(s.startIndex),d=parseStartDate(s.startDate);const fallback=people.findIndex(p=>p.inRotation);startIndex=idxById>=0&&people[idxById].inRotation?idxById:(Number.isInteger(idx)&&idx>=0&&idx<people.length&&people[idx].inRotation?idx:(fallback>=0?fallback:0));startDate=isValidMonday(d)?d:new Date(DEFAULT_START+"T00:00:00")}catch{startIndex=people.findIndex(p=>p.network==="roberto");if(startIndex<0)startIndex=0;startDate=new Date(DEFAULT_START+"T00:00:00")}}
function saveState(){localStorage.guardiasState=JSON.stringify({version:16,startIndex,startPersonId:people[startIndex]?.id||null,startDate:iso(startDate)})}
function validateLogin(network,password){const u=people.find(p=>p.network.toLowerCase()===network.toLowerCase());return u&&String(pSafe(u.password))===password?u:null}
function pSafe(v){return v==null?"":String(v)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
