async function savePersonFromAdmin(){if(!currentUser?.admin)return;const index=Number($("#personEditIndex").value),name=$("#personNameInput").value.trim(),network=$("#personNetworkInput").value.trim().toLowerCase(),email=$("#personEmailInput").value.trim().toLowerCase(),password=$("#personPasswordInput").value,role=$("#personRoleInput").value||"member",inRotation=$("#personRotationInput").checked;if(!name){showToast(t('personNameRequired'));return}if(!network){showToast(t('personNetworkRequired'));return}if(role==='viewer')$("#personRotationInput").checked=false;const finalRotation=role==='viewer'?false:inRotation;const duplicate=people.some((p,i)=>i!==index&&p.network.toLowerCase()===network);if(duplicate){showToast(t('personExists'));return}const old=index>=0?people[index]:null;const person={...(old||{id:`u-${String(Date.now())}`}),name,network,email,password:password||old?.password||"Guardia2026!",role,admin:role==='admin',inRotation:old?.alwaysOnDuty?false:finalRotation,alwaysOnDuty:!!old?.alwaysOnDuty};if(index>=0)people[index]=person;else people.push(person);if(old&&currentUser.network===old.network)currentUser=person;savePeopleState();saveState();closePersonEditor();renderAll();if(currentUser?.admin)renderAdmin();showToast(t(index>=0?'personSaved':'personAdded'))}
