async function enableNotifications(){if(localStorage.notify==='1'){disableNotifications();return}if(!(typeof Notification!=="undefined")){showToast(t('browserNotifications'));return}const permission=await Notification.requestPermission();if(permission==='granted'){localStorage.notify='1';saveNotificationPreference();updateNotifyUI();await showDutyNotification(t('notificationBody'));scheduleDutyReminder();showToast(t('notificationsOn'));}else showToast(t('notificationPermission'))}
