function saveComments(list){localStorage.guardiasComments=JSON.stringify(list)}
function commentTime(ts){const d=new Date(ts);if(Number.isNaN(d.getTime()))return language==='en'?'Date unavailable':'Fecha no disponible';return d.toLocaleString(language==='en'?'en-US':'es-NI',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function dutyMetaForDate(d){const w=weekForDate(d);return w.person?{personId:w.person.id,personName:w.person.name,start:iso(w.start),end:iso(w.end)}:null}
function commentDutyMeta(c){let start=c.dutyStart,end=c.dutyEnd;const validStart=start&&!Number.isNaN(new Date(start+'T00:00:00').getTime()),validEnd=end&&!Number.isNaN(new Date(end+'T00:00:00').getTime());if(!validStart||!validEnd){const created=new Date(c.createdAt);const m=dutyMetaForDate(created);if(m){start=m.start;end=m.end;return {start,end,personId:c.dutyPersonId||m.personId,personName:c.dutyPersonName||m.personName}}}return {start:validStart?start:null,end:validEnd?end:null,personId:c.dutyPersonId||c.authorId,personName:c.dutyPersonName||c.author}}
function filteredComments(){const list=loadComments(),date=$('#commentDateFilter')?.value||'',usr=$('#commentUserFilter')?.value||'';if(!date&&!usr)return list;return list.filter(c=>{const m=commentDutyMeta(c);const dateMatch=!date||(m.start&&m.end&&date>=m.start&&date<=m.end);const userMatch=!usr||(String(m.personId||c.authorId||c.network)===String(usr));return dateMatch&&userMatch})}
function renderCommentFilters(list){const dateInput=$('#commentDateFilter'),userSel=$('#commentUserFilter');if(!dateInput||!userSel)return;const today=iso(new Date());dateInput.max=today;const currentUserFilter=userSel.value;const users=people.map(p=>({id:p.id,name:p.name})).filter(u=>u.id&&u.name).sort((a,b)=>String(a.name).localeCompare(String(b.name),language==='en'?'en':'es'));userSel.innerHTML=`<option value="">${t('selectUser')}</option>`+users.map(u=>`<option value="${escapeHtml(String(u.id))}">${escapeHtml(String(u.name))}</option>`).join('');if([...userSel.options].some(o=>o.value===currentUserFilter))userSel.value=currentUserFilter}
function applyCommentFilters(){const date=$('#commentDateFilter')?.value||'',usr=$('#commentUserFilter')?.value||'',err=$('#commentFilterError');if(err)err.textContent='';if(date&&date>iso(new Date())){if(err)err.textContent=t('futureDate');return}if(!date||!usr){if(err)err.textContent=t('filterRequired');return}renderComments()}
function clearCommentFilters(){if($('#commentDateFilter'))$('#commentDateFilter').value='';if($('#commentUserFilter'))$('#commentUserFilter').value='';if($('#commentFilterError'))$('#commentFilterError').textContent='';renderComments()}
async function addComment(){const duty=currentDutyPerson();if(!currentUser||!duty||duty.network!==currentUser.network){showToast(t('onlyDutyCanPost'));return}const input=$('#commentInput'),text=input.value.trim(),file=$('#commentFile')?.files?.[0];if(!text&&!file)return;const meta=dutyMetaForDate(new Date());const finish=(image)=>{const item={id:`c-${Date.now()}`,authorId:currentUser.id,author:currentUser.name,network:currentUser.network,email:currentUser.email||'',text,createdAt:new Date().toISOString(),image:image||null,reactions:{},replies:[],dutyPersonId:meta?.personId||currentUser.id,dutyPersonName:meta?.personName||currentUser.name,dutyStart:meta?.start,dutyEnd:meta?.end};const list=loadComments();list.unshift(item);saveComments(list);input.value='';if($('#commentFile'))$('#commentFile').value='';$('#commentFileName').textContent='';renderComments()};if(file){if(!file.type.startsWith('image/')||file.size>3*1024*1024){showToast(language==='en'?'Use an image up to 3 MB.':'Usa una imagen de hasta 3 MB.');return}const r=new FileReader();r.onload=()=>finish(r.result);r.readAsDataURL(file)}else finish(null)}
function reactComment(id,emoji){if(!currentUser)return;const list=loadComments(),c=list.find(x=>String(x.id)===String(id));if(!c)return;c.reactions=c.reactions||{};const userKey=String(currentUser.id||currentUser.network);let previous=null;Object.keys(c.reactions).forEach(e=>{const arr=Array.isArray(c.reactions[e])?c.reactions[e]:[];if(arr.some(v=>String(v)===userKey))previous=e;c.reactions[e]=arr.filter(v=>String(v)!==userKey)});if(previous!==emoji){c.reactions[emoji]=Array.isArray(c.reactions[emoji])?c.reactions[emoji]:[];if(!c.reactions[emoji].some(v=>String(v)===userKey))c.reactions[emoji].push(userKey)}saveComments(list);renderComments();showToast(t('reactionAdded'))}
async function addReply(id){const input=$(`[data-reply-input="${id}"]`),text=input?.value.trim();if(!text||!currentUser)return;const list=loadComments(),c=list.find(x=>String(x.id)===String(id));if(!c)return;c.replies=Array.isArray(c.replies)?c.replies:[];c.replies.push({id:`r-${Date.now()}`,authorId:currentUser.id,author:currentUser.name,network:currentUser.network,text,createdAt:new Date().toISOString()});saveComments(list);input.value='';renderComments()}
function renderComments(){
 const box=$('#commentsList');if(!box)return;
 const all=loadComments();
 renderCommentFilters(all);
 const list=filteredComments();
 if(!list.length){
   const date=$('#commentDateFilter')?.value||'';
   const usr=$('#commentUserFilter')?.value||'';
   const person=people.find(p=>String(p.id)===String(usr));
   const name=person?.name||'';
   box.innerHTML=`<div class="empty-comments empty-comments-robot"><div class="empty-robot" aria-hidden="true">🤖</div><h3>${escapeHtml(name?tr('noMessagesForUser',{name}):t('noMessagesFound'))}</h3><p>${date? t('noMessagesDateHint'):t('noMessagesHint')}</p></div>`;
   return;
 }
 box.innerHTML=list.map(c=>{
   const reactions=c.reactions||{};const userKey=String(currentUser?.id||currentUser?.network||'');
   const myReaction=Object.keys(reactions).find(e=>(Array.isArray(reactions[e])?reactions[e]:[]).some(v=>String(v)===userKey));
   const reactionHtml=['👍','❤️','😂','👏'].map(e=>`<button type="button" class="reaction ${myReaction===e?'selected':''}" data-react="${escapeHtml(c.id)}" data-emoji="${e}" aria-pressed="${myReaction===e}">${e} <span>${Array.isArray(reactions[e])?reactions[e].length:0}</span></button>`).join('');
   const replies=(c.replies||[]).map(r=>`<div class="reply-item"><div class="avatar small">${initial(r.author||'?')}</div><div><b>${escapeHtml(r.author||'')}</b><span>${escapeHtml(r.text||'')}</span><small>${commentTime(r.createdAt)}</small></div></div>`).join('');
   const m=commentDutyMeta(c);
   const author=people.find(p=>String(p.id)===String(c.authorId||c.dutyPersonId));
   const authorName=c.author||author?.name||'Usuario';
   const dutyName=m.personName||people.find(p=>String(p.id)===String(m.personId))?.name||authorName;
   const dutyRange=m.start&&m.end?tr('dutyWeek',{start:fmt(new Date(m.start+'T00:00:00')),end:fmt(new Date(m.end+'T00:00:00'))}):t('dutyDateUnavailable');
   return `<article class="comment-card"><div class="comment-head"><div class="avatar">${initial(authorName)}</div><div><b>${escapeHtml(authorName)}</b><span>${escapeHtml(dutyRange)}</span><small>${commentTime(c.createdAt)}</small></div><span class="duty-badge">${t('dutyPost')}</span></div><p>${escapeHtml(c.text||'')}</p>${c.image?`<img class="comment-image" src="${c.image}" alt="">`:''}<div class="comment-actions">${reactionHtml}<button type="button" class="reply-toggle" data-reply-toggle="${escapeHtml(c.id)}">${t('reply')}</button></div><div class="replies">${replies}<div class="reply-box"><input data-reply-input="${escapeHtml(c.id)}" placeholder="${t('replyPlaceholder')}"><button type="button" data-reply-send="${escapeHtml(c.id)}" class="secondary">${t('sendReply')}</button></div></div></article>`
 }).join('');
 box.onclick=e=>{const reaction=e.target.closest('[data-react]');if(reaction&&box.contains(reaction)){e.preventDefault();e.stopPropagation();reactComment(reaction.dataset.react,reaction.dataset.emoji);return}const replySend=e.target.closest('[data-reply-send]');if(replySend&&box.contains(replySend)){e.preventDefault();addReply(replySend.dataset.replySend);return}const replyToggle=e.target.closest('[data-reply-toggle]');if(replyToggle&&box.contains(replyToggle)){e.preventDefault();const r=replyToggle.closest('.comment-card')?.querySelector('.replies');if(r)r.classList.toggle('open')}}
}
function syncComments(){return null}

function canPostComment(){const duty=currentDutyPerson();return !!(currentUser&&duty&&duty.network===currentUser.network)}
function renderCommentComposer(){const box=$("#commentComposer");if(!box)return;const duty=currentDutyPerson();const can=canPostComment();box.classList.toggle('hidden',!can);if($("#commentDutyPerson"))$("#commentDutyPerson").textContent=duty?` · ${duty.name}`:""}
function renderAll(){renderHome();renderTeam($("#search")?.value||'');renderAdmin();updateNotifyUI();renderTodayLabel();renderComments();renderCommentComposer()}
function setLanguage(next){language=next==='en'?'en':'es';localStorage.guardiasLanguage=language;applyLanguage()}
function toggleTopProfile(force){const p=$("#topProfilePanel"),btn=$("#topAvatar");if(!p)return;const open=typeof force==='boolean'?force:!p.classList.contains('open');p.classList.toggle('open',open);p.style.display=open?'block':'none';p.setAttribute('aria-hidden',String(!open));if(btn)btn.setAttribute('aria-expanded',String(open));if(open){hydrateProfile();requestAnimationFrame(()=>{const r=btn?.getBoundingClientRect();if(r){const top=Math.min(window.innerHeight-20,Math.max(8,r.bottom+10));p.style.top=Math.min(top,window.innerHeight-p.offsetHeight-10)+'px';p.style.right=Math.max(10,window.innerWidth-r.right)+'px';}})}}

let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;const b=$("#installAppBtn");if(b)b.classList.remove('hidden');});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;const b=$("#installAppBtn");if(b){b.classList.add('hidden');}showToast(language==='en'?'Guardias was installed successfully.':'Guardias se instaló correctamente.');});
async function installApp(){
  if(window.matchMedia && window.matchMedia('(display-mode: standalone)').matches){showToast(language==='en'?'Guardias is already installed.':'Guardias ya está instalada.');return;}
  if(deferredInstallPrompt){try{await deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;}catch{} deferredInstallPrompt=null; return;}
  showToast(language==='en'?'Open the browser menu and choose “Install and create shortcut”.':'Abre el menú del navegador y selecciona “Instalar y crear acceso directo”.');
}

function saveRememberPreferences(){const rememberUser=$("#rememberUser").checked,rememberPassword=$("#rememberPassword").checked;localStorage.rememberUser=rememberUser?'1':'0';localStorage.rememberPassword=rememberPassword?'1':'0';if(rememberUser)localStorage.loginNetwork=$("#loginNetwork").value.trim();else localStorage.removeItem('loginNetwork');if(rememberPassword)localStorage.loginPassword=$("#loginPassword").value;else localStorage.removeItem('loginPassword')}
function rememberedLogin(){const rememberUser=localStorage.rememberUser==='1',rememberPassword=localStorage.rememberPassword==='1';$("#rememberUser").checked=rememberUser;$("#rememberPassword").checked=rememberPassword;$("#loginNetwork").value=rememberUser?(localStorage.loginNetwork||''):'';$("#loginPassword").value=rememberPassword?(localStorage.loginPassword||''):''}
function bindRememberPreferences(){const user=$("#rememberUser"),password=$("#rememberPassword"),network=$("#loginNetwork"),pass=$("#loginPassword");user.addEventListener('change',saveRememberPreferences);password.addEventListener('change',saveRememberPreferences);network.addEventListener('input',()=>{if(user.checked)localStorage.loginNetwork=network.value.trim()});pass.addEventListener('input',()=>{if(password.checked)localStorage.loginPassword=pass.value})}
function togglePasswordVisibility(){togglePasswordField("#loginPassword","#togglePassword")}
function togglePasswordField(inputSelector,buttonSelector){const i=$(inputSelector),b=$(buttonSelector);if(!i||!b)return;const show=i.type==='password';i.type=show?'text':'password';b.textContent=show?t('hidePassword'):t('showPassword')}
function showForgotPassword(){$(".login-card").classList.add('forgot-mode');$("#loginFormWrap").classList.add('hidden');$("#forgotPanel").classList.remove('hidden');$("#forgotError").textContent='';$("#resetStep").classList.add('hidden');$("#forgotEmail").focus()}
function backToLogin(){$("#forgotPanel").classList.add('hidden');$("#loginFormWrap").classList.remove('hidden');$(".login-card").classList.remove('forgot-mode')}
let resetCode='',resetNetwork='',resetExpiresAt=0;
async function sendResetCode(){const email=$("#forgotEmail").value.trim().toLowerCase();const u=people.find(p=>String(p.email||'').toLowerCase()===email);$("#forgotError").textContent='';if(!u){$("#forgotError").textContent=t('invalidEmail');return}resetNetwork=u.network;resetCode=String(Math.floor(100000+Math.random()*900000));resetExpiresAt=Date.now()+10*60*1000;$("#resetStep").classList.remove('hidden');$("#demoResetCode").textContent=tr('demoResetCode',{code:resetCode});showToast(t('resetEmailSent'))}
async function finishReset(){const code=$("#verificationCode").value.trim(),np=$("#newPassword").value,cp=$("#confirmPassword").value;$("#resetError").textContent='';if(np!==cp){$("#resetError").textContent=t('passwordMismatch');return}if(np.length<8){$("#resetError").textContent=language==='en'?'Password must contain at least 8 characters.':'La contraseña debe tener al menos 8 caracteres.';return}if(code!==resetCode||Date.now()>resetExpiresAt){$("#resetError").textContent=t('invalidCode');return}const u=people.find(p=>p.network===resetNetwork);if(u){u.password=np;localStorage.guardiasPasswords=JSON.stringify(Object.fromEntries(people.map(x=>[x.network,x.password||''])));savePeopleState();backToLogin();showToast(t('passwordUpdated'))}}
